module chess_consistency (\n    input [3:0] num_matches,\n    input [2:0] match_k [0:15],\n    input [2:0] match_l [0:15],\n    input [15:0] match_eq,\n    output reg result\n);\n\n    parameter MAX_N = 8;\n    parameter MAX_M = 16;\n\n    // Internal matrices\n    reg [MAX_N-1:0] eq [0:MAX_N-1];   \n    reg [MAX_N-1:0] adj [0:MAX_N-1];  \n    reg [MAX_N-1:0] reach [0:MAX_N-1]; \n    reg [2:0] comp_id [0:MAX_N-1];    \n    reg inconsistent;\n\n    integer i, j, k, m;\n\n    always @(*) begin\n        // Initialize eq with identity\n        for (i = 0; i < MAX_N; i = i + 1) begin\n            for (j = 0; j < MAX_N; j = j + 1) begin\n                eq[i][j] = (i == j) ? 1'b1 : 1'b0;\n            end\n        end\n\n        // Process = matches\n        for (m = 0; m < MAX_M; m = m + 1) begin\n            if (m < num_matches && match_eq[m]) begin\n                eq[match_k[m]][match_l[m]] = 1'b1;\n                eq[match_l[m]][match_k[m]] = 1'b1;\n            end\n        end\n\n        // Compute transitive closure of eq\n        for (k = 0; k < MAX_N; k = k + 1) begin\n            for (i = 0; i < MAX_N; i = i + 1) begin\n                for (j = 0; j < MAX_N; j = j + 1) begin\n                    if (eq[i][k] && eq[k][j]) begin\n                        eq[i][j] = 1'b1;\n                    end\n                end\n            end\n        end\n\n        // Determine component representatives\n        for (i = 0; i < MAX_N; i = i + 1) begin\n            comp_id[i] = i[2:0];\n            for (j = 0; j < MAX_N; j = j + 1) begin\n                if (eq[i][j] && j < comp_id[i]) begin\n                    comp_id[i] = j[2:0];\n                end\n            end\n        end\n\n        // Initialize adj matrix to zero\n        for (i = 0; i < MAX_N; i = i + 1) begin\n            for (j = 0; j < MAX_N; j = j + 1) begin\n                adj[i][j] = 1'b0;\n            end\n        end\n\n        // Process > matches and check for immediate inconsistency\n        inconsistent = 1'b0;\n        for (m = 0; m < MAX_M; m = m + 1) begin\n            if (m < num_matches && !match_eq[m]) begin\n                if (eq[match_k[m]][match_l[m]]) begin\n                    inconsistent = 1'b1;\n                end else begin\n                    adj[comp_id[match_k[m]]][comp_id[match_l[m]]] = 1'b1;\n                end\n            end\n        end\n\n        // Compute transitive closure of adj and check for cycles\n        if (!inconsistent) begin\n            // Initialize reach matrix\n            for (i = 0; i < MAX_N; i = i + 1) begin\n                for (j = 0; j < MAX_N; j = j + 1) begin\n                    reach[i][j] = adj[i][j];\n                end\n            end\n\n            // Floyd-Warshall for reachability\n            for (k = 0; k < MAX_N; k = k + 1) begin\n                for (i = 0; i < MAX_N; i = i + 1) begin\n                    for (j = 0; j < MAX_N; j = j + 1) begin\n                        if (reach[i][k] && reach[k][j]) begin\n                            reach[i][j] = 1'b1;\n                        end\n                    end\n                end\n            end\n\n            // Check for cycles\n            for (i = 0; i < MAX_N; i = i + 1) begin\n                if (reach[i][i]) begin\n                    inconsistent = 1'b1;\n                end\n            end\n        end\n\n        // Output\n        result = !inconsistent;\n    end\n\nendmodule